`include "disciplines.vams"
module clock(u,count,r);
input u; output count; inout r; electrical u,count,r;
integer n; real next;
analog begin
@(initial_step) begin n=0; next=0.125e-6; end
@(timer(0.125e-6)) begin n=n+1; end
V(count,r)<+n;
end
endmodule

